local data = table.concat(parts)
local lookup = {}
for i = 0, 63 do
    local p = (i * MUL) % 64
    lookup[ALPHA:sub(p + 1, p + 1)] = i
end

local rev = {}
for i = #data, 1, -1 do
    rev[#rev + 1] = data:sub(i, i)
end

local buf, bits = 0, 0
local bytes = {}
for i = 1, #rev do
    local v = lookup[rev[i]]
    if v then
        buf = buf * 64 + v
        bits += 6
        if bits >= 8 then
            bits -= 8
            bytes[#bytes + 1] = math.floor(buf / (2 ^ bits)) % 256
            buf = buf % (2 ^ bits)
        end
    end
end

local out = {}
for i, b in ipairs(bytes) do
    local kb = string.byte(KEY, ((i - 1) % #KEY) + 1)
    out[i] = string.char(bit32.bxor(b, kb))
end

local ls = loadstring or load
ls(table.concat(out))()
